import {proposalEditor,proposalPanel,proposalAudit} from './integrated-proposals.js?v=5.20.0';
import {AMENDMENT_COPY,amendmentResult} from './shared/amendment-copy.js?v=5.19.0';
import {REJECTION_COPY,rejectionReasons,reasonLabel,reasonMessage,DEMO_REVIEWERS,auditTime} from './shared/rejection-copy.js?v=5.19.0';
import {SHOWCASE_COPY} from './shared/showcase-copy.js?v=5.8.0';
import {flowCopy} from './shared/flow-copy.js?v=5.11.0';
import {LANGS} from './shared/locale.js?v=5.6.0';
import {brandMark} from './shared/brand.js?v=5.6.0';
import {esc} from './shared/core.js?v=5.6.0';
const roles=l=>({...SHOWCASE_COPY[l],...flowCopy(l)});
function ownerAudit(entry){
 const c=REJECTION_COPY.ko;
 return `<article class="amendment-audit" data-audit-id="${esc(entry.id)}"><header><strong>${esc(AMENDMENT_COPY.ko[entry.kind])}</strong><span>${esc(entry.status==='pending'?AMENDMENT_COPY.ko.pending:entry.status==='rejected'?'거절':'승인')}</span></header><details class="amendment-request-record"><summary>${esc(c.request)}</summary><small>한국어</small><p lang="ko">${esc(entry.requests.ko)}</p>${entry.guestLang!=='ko'?`<small>${esc(LANGS[entry.guestLang])} · 원문</small><p lang="${entry.guestLang}">${esc(entry.requests[entry.guestLang])}</p>`:''}</details>${entry.processedAt?`<dl class="amendment-audit-meta"><div><dt>${esc(c.processedBy)}</dt><dd>${esc(entry.processedBy.name)} · ${esc(entry.processedBy.role==='owner'?'사장님':roles('ko')[entry.processedBy.role])}</dd></div><div><dt>${esc(c.processedAt)}</dt><dd><time datetime="${entry.processedAt}">${esc(auditTime(entry.processedAt))}</time></dd></div></dl>${entry.reason?`<p class="amendment-reason-tag">${esc(reasonLabel(entry.reason))}</p>`:''}<div class="amendment-audit-messages"><small>${esc(c.korean)}</small><p lang="ko">${esc(entry.messages.ko)}</p>${entry.guestLang!=='ko'?`<small>${esc(c.original)} · ${esc(LANGS[entry.guestLang])}</small><p lang="${entry.guestLang}">${esc(entry.messages[entry.guestLang])}</p>`:''}</div>`:''}${proposalAudit(entry)}</article>`;
}
export function amendmentPanel(demo,kind){
 if(demo.phase<11||demo.editing&&kind==='guest')return '';
 if(demo.scenario==='booking'&&kind==='kitchen')return proposalPanel(demo,kind);
 const lang=kind==='guest'?demo.guestLang:'ko',c=AMENDMENT_COPY[lang],r=REJECTION_COPY[lang],entry=demo.amendment;
 const button=(action,label,extra='')=>`<button type="button" data-amendment="${action}" data-run="${demo.runId}" data-revision="${demo.revision}" ${extra}>${esc(label)}</button>`;
 const controls=kind==='guest'&&demo.canManage?`<div class="amendment-guest-actions" aria-label="${esc(c.guestActions)}">${button('change',c.change)}${button('cancel',c.cancel,'class="amendment-cancel"')}</div>`:'';
 if(!entry)return controls;
 const pending=entry.status==='pending',views=demo.amendmentViews(),canReview=demo.canReview(kind),draft=demo.reviewDraft(kind),fieldId=`rejection-reason-${kind}`;
 const comparison=entry.kind==='change'&&kind!=='kitchen'?`<details class="amendment-comparison" ${pending?'open':''}><summary>${esc(c.after)}</summary><small>${esc(c.before)}</small><p>${esc(views.before.summaries[lang])}</p><small>${esc(c.after)}</small><p>${esc(views.after.summaries[lang])}</p>${kind!=='guest'&&entry.guestLang!=='ko'?`<div class="show-original"><small>${esc(LANGS[entry.guestLang])}</small><p lang="${entry.guestLang}">${esc(views.after.summaries[entry.guestLang])}</p></div>`:''}</details>`:'';
 const decisions=canReview?`<div class="amendment-review"><p class="amendment-reviewer">${esc(r.staffDemo)} · ${esc(DEMO_REVIEWERS[kind].name)} · ${esc(kind==='owner'?'사장님':roles(lang)[kind])}</p>${button('approve',c.approve,`data-actor="${kind}" data-request-id="${entry.id}"`)}<div class="amendment-rejection"><label for="${fieldId}">${esc(r.reason)}</label><select id="${fieldId}" data-rejection-reason data-actor="${kind}" data-request-id="${entry.id}" data-run="${demo.runId}" data-revision="${demo.revision}" aria-describedby="${fieldId}-error ${fieldId}-preview" aria-invalid="${draft.error}"><option value="">${esc(r.choose)}</option>${rejectionReasons(entry).map(id=>`<option value="${id}" ${draft.reason===id?'selected':''}>${esc(reasonLabel(id,lang))}</option>`).join('')}</select><p id="${fieldId}-error" class="rejection-error" role="alert" ${draft.error?'':'hidden'}>${esc(r.required)}</p><div class="rejection-preview" id="${fieldId}-preview" ${draft.reason?'':'hidden'}><small>${esc(r.preview)} · ${esc(LANGS[entry.guestLang])}</small><p lang="${entry.guestLang}" data-rejection-preview>${esc(draft.reason?AMENDMENT_COPY[entry.guestLang].rejected+' '+reasonMessage(draft.reason,entry.guestLang):'')}</p></div>${proposalEditor(demo,kind)}${button('reject',demo.proposalDraft(kind)?'거절하고 대안 보내기':c.reject,`data-actor="${kind}" data-request-id="${entry.id}" class="amendment-reject"`)}</div></div>`:'';
 const history=kind==='owner'?`<details class="amendment-history amendment-owner-history" ${pending?'':'open'}><summary>${esc(r.audit)} · ${demo.history.length}</summary><p class="amendment-audit-note">${esc(r.staffDemo)} · 주모 · UTC+7</p>${[...demo.history].reverse().map(ownerAudit).join('')}</details>`:`<details class="amendment-history"><summary>${esc(c.history)} · ${demo.history.length}</summary><ol>${demo.history.map(h=>`<li>${esc(c[h.kind])} · ${esc(amendmentResult(h,lang))}${h.by?` · ${esc(roles(lang)[h.by])}`:''}</li>`).join('')}</ol></details>`;
 return `<section class="amendment-card ${entry.status}" data-amendment-status="${entry.status}" lang="${lang}"><div class="amendment-title">${brandMark(pending?'thinking':'greeting',true)}<strong>${esc(c[entry.kind])}</strong></div><p class="amendment-result" role="status">${esc(amendmentResult(entry,lang))}</p>${pending?`<p>${esc(c[entry.requiredRole==='owner'?'ownerOnly':'staffCan'])}</p><p class="amendment-hold">${esc(c.holding)}</p>`:`<small>${esc(roles(lang)[entry.by])}</small>`}${comparison}${decisions}</section>${proposalPanel(demo,kind)}${controls}${history}`;
}
